package it.cavallium.rockserver.core.common.distributed;

import java.io.*;
import java.util.*;

/** COMPLETE archive graph; its destination owner must verify and force all referenced bytes before publication. */
public final class DatabaseBackupManifest {
    public record Destination(UUID archiveId,UUID failureDomainId){public Destination{Objects.requireNonNull(archiveId);Objects.requireNonNull(failureDomainId);}}
    /** Binding of actual node/pool cohort work, not authentication of a native capture. */
    public record Cohort(UUID nodeIncarnation,UUID poolId,UUID cohortId,Set<UUID> groups){public Cohort{Objects.requireNonNull(nodeIncarnation);Objects.requireNonNull(poolId);Objects.requireNonNull(cohortId);groups=Set.copyOf(groups);if(groups.isEmpty())throw new IllegalArgumentException("Empty capture cohort");}}
    public record Chunk(UUID domainId,UUID groupId,UUID columnId,long ordinal,ApplyPosition cut,byte[] lowerInclusive,byte[] upperExclusive,UUID objectId,long bytes,byte[] sha256,long entries,byte[] firstKey,byte[] lastKey){
        public Chunk{Objects.requireNonNull(domainId);Objects.requireNonNull(groupId);Objects.requireNonNull(columnId);Objects.requireNonNull(cut);Objects.requireNonNull(sha256);if(ordinal<0 || cut.term()<1 || bytes<0 || entries<0 || lowerInclusive!=null && upperExclusive!=null && Arrays.compareUnsigned(lowerInclusive,upperExclusive)>=0)throw new IllegalArgumentException("Invalid backup chunk scope");
            if(entries==0 ? objectId!=null || bytes!=0 || sha256.length!=0 || firstKey!=null || lastKey!=null : objectId==null || bytes<1 || bytes>NativeSstImportManifest.MAX_FILE_BYTES || sha256.length!=32 || firstKey==null || lastKey==null || Arrays.compareUnsigned(firstKey,lastKey)>0 || lowerInclusive!=null && Arrays.compareUnsigned(firstKey,lowerInclusive)<0 || upperExclusive!=null && Arrays.compareUnsigned(lastKey,upperExclusive)>=0)throw new IllegalArgumentException("Invalid archive USER object");
            for(var key:new byte[][]{lowerInclusive,upperExclusive,firstKey,lastKey})if(key!=null && key.length>NativeSstImportManifest.MAX_KEY_BYTES)throw new IllegalArgumentException("Backup key bound exceeds limit");lowerInclusive=BackupData.nullable(lowerInclusive);upperExclusive=BackupData.nullable(upperExclusive);firstKey=BackupData.nullable(firstKey);lastKey=BackupData.nullable(lastKey);sha256=sha256.clone();}
        @Override public byte[] lowerInclusive(){return BackupData.nullable(lowerInclusive);}@Override public byte[] upperExclusive(){return BackupData.nullable(upperExclusive);}@Override public byte[] firstKey(){return BackupData.nullable(firstKey);}@Override public byte[] lastKey(){return BackupData.nullable(lastKey);}@Override public byte[] sha256(){return sha256.clone();}
    }
    public record OperatorAsset(UUID objectId,byte[] sha256,long bytes){public OperatorAsset{Objects.requireNonNull(objectId);if(sha256.length!=32 || bytes<1 || bytes>8*1024*1024)throw new IllegalArgumentException("Invalid archived operator");sha256=sha256.clone();}@Override public byte[] sha256(){return sha256.clone();}}
    private final DatabaseBackupDefinition definition;private final Destination destination;private final List<SnapshotFenceStatus> held;private final List<Cohort> cohorts;private final List<Chunk> chunks;private final List<OperatorAsset> operators;private final Map<UUID,SnapshotFenceStatus.Capture> captures;private final byte[] encoded;
    public DatabaseBackupManifest(DatabaseBackupDefinition definition,Destination destination,Collection<SnapshotFenceStatus> held,Collection<Cohort> cohorts,Collection<Chunk> chunks,Collection<OperatorAsset> operators){
        this.definition=Objects.requireNonNull(definition);this.destination=Objects.requireNonNull(destination);this.held=held.stream().sorted(Comparator.comparing(s->s.fence().fenceId(),RangeDirectoryCodec.UUID_ORDER)).toList();this.cohorts=cohorts.stream().sorted(Comparator.comparing(Cohort::cohortId,RangeDirectoryCodec.UUID_ORDER)).toList();this.chunks=chunks.stream().sorted(Comparator.comparing(Chunk::domainId,RangeDirectoryCodec.UUID_ORDER).thenComparing(Chunk::groupId,RangeDirectoryCodec.UUID_ORDER).thenComparing(Chunk::columnId,RangeDirectoryCodec.UUID_ORDER).thenComparingLong(Chunk::ordinal)).toList();this.operators=operators.stream().sorted(Comparator.comparing(OperatorAsset::objectId,RangeDirectoryCodec.UUID_ORDER)).toList();
        var expected=new HashMap<UUID,SnapshotFence>();for(var domain:definition.domains())for(var fence:domain.fences())expected.put(fence.fenceId(),fence);var cuts=new HashMap<UUID,SnapshotFenceStatus.Capture>();
        for(var status:this.held){var fence=expected.remove(status.fence().fenceId());if(fence==null || !Arrays.equals(fence.encode(),status.fence().encode()) || status.phase()!=SnapshotFenceStatus.Phase.INSTALLING || !status.allReady())throw new IllegalArgumentException("Backup capture lacks original held global barrier");for(var participant:fence.participants()){var capture=status.progress(participant.groupId()).capture();if(capture==null || cuts.put(participant.groupId(),capture)!=null)throw new IllegalArgumentException("Backup capture missing or duplicated");}}
        if(!expected.isEmpty())throw new IllegalArgumentException("Missing backup subfence captures");captures=Map.copyOf(cuts);var cohortGroups=new HashSet<UUID>();var pools=new HashSet<String>();var cohortIds=new HashSet<UUID>();
        for(var cohort:this.cohorts){if(!cohortIds.add(cohort.cohortId()) || !pools.add(cohort.nodeIncarnation()+"/"+cohort.poolId()))throw new IllegalArgumentException("A node/pool must use one native cohort");for(var group:cohort.groups()){if(!cuts.containsKey(group) || !cohortGroups.add(group))throw new IllegalArgumentException("Cohort coverage changed");var range=range(group);if(range.replicas().stream().noneMatch(r->r.nodeIncarnation().equals(cohort.nodeIncarnation())))throw new IllegalArgumentException("Capture cohort has no configured source owner");}}
        if(!cohortGroups.equals(cuts.keySet()))throw new IllegalArgumentException("Missing database capture cohort");if(this.chunks.size()>definition.limits().maximumChunks())throw new IllegalArgumentException("Backup chunk count exceeds global limit");
        var objects=new HashSet<UUID>();long total=0;var pairs=new HashMap<String,List<Chunk>>();for(var chunk:this.chunks){var domain=definition.domain(chunk.domainId());var range=domain.directory().ranges().stream().filter(r->r.groupId().equals(chunk.groupId())).findFirst().orElseThrow(()->new IllegalArgumentException("Foreign backup group"));if(!domain.directory().columns().contains(chunk.columnId()) || !chunk.cut().equals(cuts.get(chunk.groupId()).position()))throw new IllegalArgumentException("Archive chunk changed captured schema/column/cut");if(chunk.objectId()!=null && !objects.add(chunk.objectId()))throw new IllegalArgumentException("Archive object reused");total=Math.addExact(total,chunk.bytes());pairs.computeIfAbsent(chunk.groupId()+"/"+chunk.columnId(),ignored->new ArrayList<>()).add(chunk);}
        for(var domain:definition.domains())for(var range:domain.directory().ranges())for(var column:domain.directory().columns()){var pieces=pairs.remove(range.groupId()+"/"+column);if(pieces==null)throw new IllegalArgumentException("Archive column coverage missing");byte[] next=range.lowerInclusive();long ordinal=0;for(var piece:pieces){if(ordinal>0 && piece.lowerInclusive()==null || piece.upperExclusive()==null && ordinal!=pieces.size()-1 || piece.ordinal()!=ordinal++ || !Arrays.equals(next,piece.lowerInclusive()))throw new IllegalArgumentException("Archive pieces overlap, gap or reorder");next=piece.upperExclusive();}if(!Arrays.equals(next,range.upperExclusive()))throw new IllegalArgumentException("Archive column coverage incomplete");}if(!pairs.isEmpty())throw new IllegalArgumentException("Foreign archive coverage");
        var required=new HashSet<String>();for(var domain:definition.domains())for(var column:domain.schema().columns())if(column.operator()!=null)required.add(HexFormat.of().formatHex(column.operator().artifactSha256()));for(var operator:this.operators){if(!objects.add(operator.objectId()) || !required.remove(HexFormat.of().formatHex(operator.sha256())))throw new IllegalArgumentException("Changed/duplicate archived operator");total=Math.addExact(total,operator.bytes());}if(!required.isEmpty() || total>definition.limits().maximumArchiveBytes())throw new IllegalArgumentException("Archive operators missing or destination bound exceeded");encoded=serialize();
    }
    public DatabaseBackupDefinition definition(){return definition;}public Destination destination(){return destination;}public List<SnapshotFenceStatus> heldCaptures(){return held;}public List<Cohort> cohorts(){return cohorts;}public List<Chunk> chunks(){return chunks;}public List<OperatorAsset> operators(){return operators;}public Map<UUID,SnapshotFenceStatus.Capture> captures(){return captures;}public byte[] encode(){return encoded.clone();}
    private RangeDescriptor range(UUID group){return definition.domains().stream().flatMap(d->d.directory().ranges().stream()).filter(r->r.groupId().equals(group)).findFirst().orElseThrow();}
    private byte[] serialize(){return BackupData.bytes(out->{out.writeInt(0x4442434d);BackupData.blob(out,definition.encode());BackupData.uuid(out,destination.archiveId());BackupData.uuid(out,destination.failureDomainId());out.writeInt(held.size());for(var status:held)BackupData.blob(out,status.encode());out.writeInt(cohorts.size());for(var cohort:cohorts){BackupData.uuid(out,cohort.nodeIncarnation());BackupData.uuid(out,cohort.poolId());BackupData.uuid(out,cohort.cohortId());out.writeInt(cohort.groups().size());for(var group:cohort.groups().stream().sorted(RangeDirectoryCodec.UUID_ORDER).toList())BackupData.uuid(out,group);}out.writeInt(chunks.size());for(var chunk:chunks){BackupData.uuid(out,chunk.domainId());BackupData.uuid(out,chunk.groupId());BackupData.uuid(out,chunk.columnId());out.writeLong(chunk.ordinal());out.writeLong(chunk.cut().term());out.writeLong(chunk.cut().index());BackupData.bound(out,chunk.lowerInclusive());BackupData.bound(out,chunk.upperExclusive());out.writeBoolean(chunk.objectId()!=null);if(chunk.objectId()!=null)BackupData.uuid(out,chunk.objectId());out.writeLong(chunk.bytes());BackupData.blob(out,chunk.sha256());out.writeLong(chunk.entries());BackupData.bound(out,chunk.firstKey());BackupData.bound(out,chunk.lastKey());}out.writeInt(operators.size());for(var asset:operators){BackupData.uuid(out,asset.objectId());out.writeLong(asset.bytes());out.write(asset.sha256());}},definition.limits().maximumMetadataBytes());}
    public static DatabaseBackupManifest decode(byte[] bytes){return BackupData.read(bytes,DatabaseBackupDefinition.MAX_BYTES,in->{if(in.readInt()!=0x4442434d)throw new IOException("Wrong COMPLETE archive");var definition=DatabaseBackupDefinition.decode(BackupData.blob(in,DatabaseBackupDefinition.MAX_BYTES));var destination=new Destination(BackupData.uuid(in),BackupData.uuid(in));int n=BackupData.count(in,DatabaseBackupDefinition.MAX_RANGES);var held=new ArrayList<SnapshotFenceStatus>();for(int j=0;j<n;j++)held.add(SnapshotFenceStatus.decode(BackupData.blob(in,SnapshotFenceStatus.MAX_BYTES)));n=BackupData.count(in,DatabaseBackupDefinition.MAX_RANGES,52);var cohorts=new ArrayList<Cohort>();for(int j=0;j<n;j++){UUID node=BackupData.uuid(in),pool=BackupData.uuid(in),cohort=BackupData.uuid(in);int count=BackupData.count(in,DatabaseBackupDefinition.MAX_RANGES,16);var groups=new HashSet<UUID>();for(int k=0;k<count;k++)if(!groups.add(BackupData.uuid(in)))throw new IOException("Duplicate cohort group");cohorts.add(new Cohort(node,pool,cohort,groups));}n=BackupData.count(in,definition.limits().maximumChunks(),109);var chunks=new ArrayList<Chunk>();for(int j=0;j<n;j++){UUID domain=BackupData.uuid(in),group=BackupData.uuid(in),column=BackupData.uuid(in);long ordinal=in.readLong();var cut=new ApplyPosition(in.readLong(),in.readLong());byte[] lower=BackupData.bound(in),upper=BackupData.bound(in);boolean present=in.readBoolean();UUID object=present?BackupData.uuid(in):null;long size=in.readLong();byte[] hash=BackupData.blob(in,32);long rows=in.readLong();chunks.add(new Chunk(domain,group,column,ordinal,cut,lower,upper,object,size,hash,rows,BackupData.bound(in),BackupData.bound(in)));}n=BackupData.count(in,definition.limits().maximumColumnPairs(),56);var assets=new ArrayList<OperatorAsset>();for(int j=0;j<n;j++){UUID object=BackupData.uuid(in);long size=in.readLong();assets.add(new OperatorAsset(object,in.readNBytes(32),size));}var result=new DatabaseBackupManifest(definition,destination,held,cohorts,chunks,assets);BackupData.canonical(bytes,result.encode());return result;});}
}
